-- TASK-0065 Open Hand teaching items: ap-statistics (4 items). Generated by
-- scripts/content-seed/task0065_load/build_load_sql.py. Idempotent: re-running
-- skips content_keys already present in the target pack.
do $oht0065$
declare
  v_subject text := 'ap-statistics';
  v_tsv uuid := 'dae3c72e-82ca-4960-9552-1b034bd347e5';
  v_owner uuid := (select p.user_id from app.profiles p where p.user_id = 'f5a26c6b-3566-4d58-9e97-979fbb947564');
  v_items jsonb := $oht0065json$[{"content_key":"APSTATS-OHT-1.12","topic_code":"1.12","title":"Potential Problems with Sampling","stem":"A teacher has a numbered roster of 350 students (001 to 350) and wants a simple random sample of 20 students using a random number generator. Which procedure is complete and correct?","choices":[{"choice_key":"A","choice_text":"Generate 20 random numbers with the generator and choose those students from the roster.","is_correct":false,"rationale":"Tempting if you think 'use a random number generator' is a complete description of an SRS — but without the range 001 to 350 and a rule for repeats, two people could carry it out differently. Fix: write the procedure so a stranger could follow it: give the number range, say how repeats are handled, and say when to stop."},{"choice_key":"B","choice_text":"Generate three-digit numbers from 001 to 350, skip any repeated number, and continue until 20 different students are chosen.","is_correct":true,"rationale":"This earns the point because it states the range, handles repeats, and maps each number to one student on the labeled list. Skipping repeats keeps every group of 20 students equally likely."},{"choice_key":"C","choice_text":"Generate numbers from 001 to 350 and keep every number produced, even if a student appears twice, until 20 numbers are used.","is_correct":false,"rationale":"Tempting if you think discarding a repeated number interferes with randomness, so you keep every number the generator gives — but keeping repeats can select the same student twice, leaving fewer than 20 different students. Fix: add the rule 'ignore repeated numbers' and keep going until 20 different students are chosen."},{"choice_key":"D","choice_text":"Pick a random starting student from 1 to 17 and then take every 17th student on the roster.","is_correct":false,"rationale":"Tempting if you confuse a systematic sample, which uses one random start, with a simple random sample — but after the start every other pick is fixed, so many groups of 20, such as 20 students in a row on the roster, can never be chosen. Fix: ask whether every possible group of 20 could be the sample, and if not, reject the method as an SRS."}]},{"content_key":"APSTATS-OHT-2.3","topic_code":"2.3","title":"Estimating Probabilities Using Simulation","stem":"A basketball player makes 70% of her free throws. A student wants to estimate by simulation the probability that she makes at least 3 of her next 4 free throws, using a random digit table with digits 0 to 9. Which design is valid?","choices":[{"choice_key":"A","choice_text":"Let digits 1 to 7 be a made shot and 8 and 9 a miss, skipping 0; one trial is four digits.","is_correct":false,"rationale":"Tempting if you count 7 'make' digits and forget that skipping 0 leaves only 9 equally likely digits — so a make gets probability 7/9, about 78%, not 70%. Fix: compute (number of make digits) / (number of digits in use) and check that it equals 0.70."},{"choice_key":"B","choice_text":"Let digits 0 to 6 be a made shot and 7 to 9 a miss; one trial is a single digit; record the percent of made shots.","is_correct":false,"rationale":"Tempting if you mix up one shot with one trial and simulate the shots one digit at a time — but the event 'at least 3 of 4 made' needs four shots per trial, and the percent of made shots estimates 0.70, not the target probability. Fix: define one trial as one full run of the process (four shots) and record whether the event happened in that trial."},{"choice_key":"C","choice_text":"Let digits 0 to 6 be a made shot and 7 to 9 a miss; one trial is four digits; record whether at least three are made; repeat for many trials.","is_correct":true,"rationale":"This earns the point because 7 of 10 digits give a 70% chance per shot, one trial models the four shots, and the recorded result is the event of interest. Many repeated trials let the relative frequency approach the true probability."},{"choice_key":"D","choice_text":"Let digits 0 to 6 be a made shot, use four digits, but run only four trials and report that proportion.","is_correct":false,"rationale":"Tempting if you confuse the four shots within a trial with the number of trials to run — but with only four trials the estimate can only be 0, 0.25, 0.5, 0.75 or 1 and swings widely from run to run. Fix: run many trials (for example, 100 or more) so the relative frequency settles near the true probability."}]},{"content_key":"APSTATS-OHT-3.6","topic_code":"3.6","title":"p-Values","stem":"A significance test of H₀: p = 0.30 versus Hₐ: p > 0.30 produces a p-value of 0.03. Which interpretation of the p-value is correct?","choices":[{"choice_key":"A","choice_text":"There is a 3% chance that the null hypothesis H₀ is true, given the sample result.","is_correct":false,"rationale":"Tempting if you flip the condition and read the p-value as the probability that H₀ is true given the data — but the p-value is computed by assuming H₀ is true, so it cannot be the probability that H₀ is true. Fix: begin every p-value interpretation with 'Assuming H₀ is true,' and then describe the chance of a result at least as extreme as the one observed."},{"choice_key":"B","choice_text":"There is a 97% chance that the alternative hypothesis Hₐ is true, given the sample result.","is_correct":false,"rationale":"Tempting if you subtract the p-value from 1 and read 0.97 as the probability that Hₐ is true — but a p-value gives no probability for either hypothesis. Fix: do not subtract the p-value from 1; interpret 0.03 directly as the chance of a result this extreme if H₀ is true."},{"choice_key":"C","choice_text":"If the true proportion were 0.30, there would be a 3% chance of getting a sample proportion at least as large as the one observed.","is_correct":true,"rationale":"This earns the point because a p-value is computed assuming H₀ is true and measures how unusual the sample result is under that assumption."},{"choice_key":"D","choice_text":"The sample proportion is 3 percentage points above the hypothesized value of 0.30.","is_correct":false,"rationale":"Tempting if you read 0.03 on the same scale as the proportion 0.30 and treat it as the gap between the sample proportion and 0.30 — but the p-value is a probability, not a difference in proportions. Fix: when you see a p-value, ask 'the probability of what?' and answer with the chance of a sample proportion at least as large as the observed one under H₀."}]},{"content_key":"APSTATS-OHT-3.14","topic_code":"3.14","title":"Setting Up a Chi-Square Test for Homogeneity or Independence","stem":"A researcher randomly selects 300 adults from one city and records each person's age group (18–34, 35–54, 55 and over) and preferred news source (TV, online, print). The counts are displayed in a table. Which chi-square test applies, and why?","choices":[{"choice_key":"A","choice_text":"A test of homogeneity, because the table compares news source across the three age groups.","is_correct":false,"rationale":"Tempting if you choose the test from the table's layout, seeing the three age groups as separate groups to compare — but homogeneity requires a separate random sample (or randomly assigned treatment group) for each group, and here one sample of 300 was classified two ways. Fix: ask 'how many samples were taken?' and, when it is one sample measured on two variables, choose independence."},{"choice_key":"B","choice_text":"A two-sample z-test for proportions, because age groups are being compared.","is_correct":false,"rationale":"Tempting if you see 'compare groups' and reach for the two-sample test for proportions you already know — but that test compares two groups on a yes/no outcome, and here there are three age groups and three news sources. Fix: count the rows and columns of the table, and if either is more than two, use a chi-square test."},{"choice_key":"C","choice_text":"A test of independence, because one random sample was classified on two categorical variables.","is_correct":true,"rationale":"This earns the point because homogeneity versus independence depends on the study design. One sample, cross-classified by two variables, calls for independence."},{"choice_key":"D","choice_text":"A test of homogeneity, because chi-square tests with three rows always test whether distributions are the same.","is_correct":false,"rationale":"Tempting if you rely on a memorized shortcut such as 'three rows means homogeneity' — but the choice between homogeneity and independence depends on how the data were collected, not on the number of rows. Fix: decide from the sampling design: separate samples per group means homogeneity, one sample with two variables means independence."}]}]$oht0065json$::jsonb;
  v_pv uuid; v_npv int;
  r jsonb; c jsonb;
  v_ci uuid; v_civ uuid; v_key text; v_correct text;
  v_loaded int := 0; v_skipped int := 0; v_released int := 0;
begin
  select count(*) into v_npv
  from app.exam_pack_versions epv join app.exam_packs ep on ep.id = epv.exam_pack_id
  join app.subjects s on s.id = ep.subject_id
  where s.subject_key = v_subject and epv.status = 'published' and epv.retired_at is null;
  if v_npv = 0 then
    raise exception 'task0065: no published, non-retired exam pack version for %', v_subject;
  end if;
  -- Prefer the published pack that already holds teaching items (two exist for
  -- Statistics in Development); otherwise require exactly one.
  select epv.id into v_pv
  from app.exam_pack_versions epv join app.exam_packs ep on ep.id = epv.exam_pack_id
  join app.subjects s on s.id = ep.subject_id
  where s.subject_key = v_subject and epv.status = 'published' and epv.retired_at is null
    and (v_npv = 1 or exists (select 1 from app.open_hand_teaching_items t
                              join app.content_items ci on ci.id = t.content_item_id
                              where ci.exam_pack_version_id = epv.id))
  order by (select count(*) from app.open_hand_teaching_items t join app.content_items ci on ci.id = t.content_item_id
            where ci.exam_pack_version_id = epv.id) desc, epv.id
  limit 1;
  if v_pv is null then
    raise exception 'task0065: % has % published packs and none holds teaching items; pick one explicitly', v_subject, v_npv;
  end if;

  for r in select * from jsonb_array_elements(v_items) loop
    v_key := r->>'content_key';
    if exists (select 1 from app.content_items where exam_pack_version_id = v_pv and content_key = v_key) then
      v_skipped := v_skipped + 1;
      continue;
    end if;
    if jsonb_array_length(r->'choices') <> 4
       or (select count(*) from jsonb_array_elements(r->'choices') x where (x->>'is_correct')::boolean) <> 1 then
      raise exception 'task0065: % must have 4 choices with exactly one correct', v_key;
    end if;
    if not exists (select 1 from app.taxonomy_topics tt where tt.taxonomy_source_version = v_tsv
                   and tt.topic_code = r->>'topic_code') then
      raise exception 'task0065: topic % not in taxonomy %', r->>'topic_code', v_tsv;
    end if;
    select x->>'choice_key' into v_correct from jsonb_array_elements(r->'choices') x
    where (x->>'is_correct')::boolean;

    insert into app.content_items (exam_pack_version_id, content_key, item_type, title, status)
    values (v_pv, v_key, 'mcq', r->>'title', 'draft')
    returning id into v_ci;

    insert into app.content_item_versions (content_item_id, version_num, stem, content_hash, status,
      review_status, rubric_type, evaluator_strategy, canonical_answer_1)
    values (v_ci, 1, r->>'stem', md5(v_key), 'draft', 'tutor_review_pending', 'mcq', 'rule_based_mcq', v_correct)
    returning id into v_civ;

    for c in select * from jsonb_array_elements(r->'choices') loop
      insert into app.mcq_choices (content_item_version_id, choice_key, choice_text, is_correct, rationale)
      values (v_civ, c->>'choice_key', c->>'choice_text', (c->>'is_correct')::boolean, c->>'rationale');
    end loop;

    insert into app.content_item_cells (content_item_version_id, content_item_id, taxonomy_source_version,
      topic_code, skill_code, is_primary, assignment_status, source, model_run_id)
    values (v_civ, v_ci, v_tsv, r->>'topic_code', null, true, 'authored', 'task0065_oht_generated_2026_10_06',
      'TASK-0065 Open Hand teaching batch 2026-10-06 (authored to this topic; checked per CHECK_RESULTS.md)');

    -- Publish gates: enforce_publish_gate (approved review_status),
    -- tg_content_pipeline_guard_publish (published only from reviewed_approved),
    -- enforce_mcq_stem_choice_sync (runs on publish; choices exist by now).
    update app.content_item_versions set status = 'reviewed_approved', review_status = 'question_review_approved',
      approved_by = v_owner, approved_at = now() where id = v_civ;
    update app.content_item_versions set status = 'published', published_at = now() where id = v_civ;
    update app.content_items set status = 'reviewed_approved' where id = v_ci;
    update app.content_items set status = 'published' where id = v_ci;

    insert into app.open_hand_teaching_items (content_item_id, topic_code, source, note)
    values (v_ci, r->>'topic_code', 'generated', 'TASK-0065 batch 2026-10-06')
    on conflict (content_item_id) do nothing;
    v_loaded := v_loaded + 1;
  end loop;

  -- Return superseded spares (same subject + topic) to scoring.
  with rel as (
    update app.open_hand_teaching_items t set released_at = now()
    from app.content_items ci, app.exam_pack_versions epv, app.exam_packs ep, app.subjects s
    where ci.id = t.content_item_id and epv.id = ci.exam_pack_version_id and ep.id = epv.exam_pack_id
      and s.id = ep.subject_id and s.subject_key = v_subject
      and t.source = 'spare' and t.released_at is null
      and exists (select 1 from app.open_hand_teaching_items g
                  join app.content_items gci on gci.id = g.content_item_id
                  where g.source = 'generated' and g.released_at is null and g.note = 'TASK-0065 batch 2026-10-06'
                    and g.topic_code = t.topic_code and gci.exam_pack_version_id = v_pv
                    and gci.status = 'published')
    returning t.content_item_id)
  select count(*) into v_released from rel;

  raise notice 'task0065 %: pack %, loaded %, skipped %, spares released %', v_subject, v_pv, v_loaded, v_skipped, v_released;
end
$oht0065$;
